const fs=require('fs');
const path=require('path');
const crypto=require('crypto');
const puppeteer=require('puppeteer-core');
const BASE='http://127.0.0.1:4173/';
const SHA='a1fda66759397c1083149a1d1e1eb400f1ba0baf';
const OUT=process.env.OUT; const CHROME=process.env.CHROME;
if(!OUT||!CHROME) throw new Error('missing env');
fs.mkdirSync(path.join(OUT,'screenshots'),{recursive:true}); fs.mkdirSync(path.join(OUT,'reports'),{recursive:true});
const expected={'player inline CSS':'304201e768beb75f4a8c00f50da66a44a2fc3ee116eec2da588cc3ec6c248848','hero/player markup':'d9c6628f5451049921b2a0bfd1f5f174c8c482101b156473204dd2a1c8012e9f','player behavior script':'1e1697cce9df7d454022d27a9925095a3a0b5a4f27c8a88dc02e4916b6d9afe1'};
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
const html=fs.readFileSync('index.html','utf8');
const ss=html.indexOf('  <style>'), se=html.indexOf('  </style>',ss);
const hs=html.indexOf('    <section class="hero hero-film-hero"'), he=html.indexOf('    <section class="home-thesis"',hs);
const marker='  <script src="assets/site.js" defer></script>', me=html.indexOf(marker)+marker.length, js=html.indexOf('  <script>',me), je=html.indexOf('  </script>',js);
const actual={'player inline CSS':sha(html.slice(ss,se+'  </style>'.length)),'hero/player markup':sha(html.slice(hs,he)),'player behavior script':sha(html.slice(js,je+'  </script>'.length))};
const filmHashPass=Object.keys(expected).every(k=>expected[k]===actual[k]);
fs.writeFileSync(path.join(OUT,'reports','film-hashes.json'),JSON.stringify({expected,actual,pass:filmHashPass},null,2));
if(!filmHashPass)throw new Error('protected film hash mismatch');
const viewports=[{w:1920,h:1080},{w:1440,h:900},{w:768,h:1024},{w:390,h:844},{w:360,h:800}];
const errors=[],results=[];
(async()=>{const browser=await puppeteer.launch({executablePath:CHROME,headless:true,args:['--no-sandbox','--disable-setuid-sandbox']});try{for(const vp of viewports){const page=await browser.newPage();await page.setCacheEnabled(false);await page.setViewport({width:vp.w,height:vp.h,deviceScaleFactor:1});const ce=[],pe=[],failed=[],bad=[];page.on('console',m=>{if(m.type()==='error')ce.push(m.text())});page.on('pageerror',e=>pe.push(String(e)));page.on('requestfailed',r=>failed.push({url:r.url(),error:r.failure()?.errorText||''}));page.on('response',r=>{if(r.status()>=400)bad.push({url:r.url(),status:r.status()})});const response=await page.goto(BASE+'index.html?fix01='+Date.now(),{waitUntil:'domcontentloaded',timeout:45000});await page.waitForSelector('.home-hero-positioning',{visible:true,timeout:10000});await page.evaluate(()=>{const v=document.getElementById('holding-film');if(v){try{v.pause();v.currentTime=0}catch{}}});await new Promise(r=>setTimeout(r,900));const state=await page.evaluate(()=>{const rr=e=>{const b=e.getBoundingClientRect();return{left:b.left,top:b.top,right:b.right,bottom:b.bottom,width:b.width,height:b.height}};const o=document.querySelector('.home-hero-positioning'),t=document.querySelector('.home-hero-positioning__title'),l=document.querySelector('.home-hero-positioning__location'),h=document.querySelector('.site-header'),v=document.getElementById('holding-film');const controls=[...document.querySelectorAll('.hero-film-controls button:not([hidden]),.hero-film-controls input:not([hidden]),.hero-film-time')];const or=rr(o),hr=rr(h),vr=rr(v),cr=controls.map(rr);const intersects=(a,b)=>a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;const ls=getComputedStyle(l);return{overlay:or,header:hr,video:vr,controlCollision:cr.some(c=>intersects(or,c)),headerCollision:intersects(or,hr),overflowX:document.documentElement.scrollWidth-document.documentElement.clientWidth,titleText:[...t.querySelectorAll('span')].map(x=>x.textContent.trim()),supportText:l.textContent.trim(),supportTextTransform:ls.textTransform,visible:getComputedStyle(o).visibility!=='hidden'&&getComputedStyle(o).display!=='none',pointerEvents:getComputedStyle(o).pointerEvents,videoSource:document.querySelector('#holding-film source')?.getAttribute('src'),poster:v.getAttribute('poster'),captionTrack:document.querySelector('#holding-film track')?.getAttribute('src')};});const key=`${vp.w}x${vp.h}`;const lf=failed.filter(x=>x.url.startsWith(BASE)),lb=bad.filter(x=>x.url.startsWith(BASE));if(!response||response.status()!==200)errors.push(`${key}: nav`);if(state.titleText.join('|')!=='Industrial trade.|Technology.|Intelligence.')errors.push(`${key}: title copy`);if(state.supportText!=='Operating from Istanbul.')errors.push(`${key}: support copy`);if(state.supportTextTransform!=='none')errors.push(`${key}: support casing transform=${state.supportTextTransform}`);if(!state.visible)errors.push(`${key}: invisible`);if(state.headerCollision)errors.push(`${key}: header collision`);if(state.controlCollision)errors.push(`${key}: control collision`);if(state.overflowX>1)errors.push(`${key}: overflow ${state.overflowX}`);if(ce.length||pe.length||lf.length||lb.length)errors.push(`${key}: browser/network error`);if(state.pointerEvents!=='none')errors.push(`${key}: pointer capture`);if(state.videoSource!=='assets/media/unique-holding-film-720p.mp4'||state.captionTrack!=='assets/media/unique-holding-caption.vtt')errors.push(`${key}: film source/track drift`);const shot=`homepage-fix01-${key}.png`;await page.screenshot({path:path.join(OUT,'screenshots',shot),fullPage:false});results.push({viewport:key,status:response?.status(),...state,consoleErrors:ce,pageErrors:pe,failedRequests:lf,badResponses:lb,screenshot:shot});await page.close();}}finally{await browser.close()}const report={status:errors.length?'FAIL':'PASS',candidateSha:SHA,filmHashPass,visualCases:results.length,errors,viewports:results};fs.writeFileSync(path.join(OUT,'homepage-fix01-browser-qa.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({status:report.status,filmHashPass,visualCases:results.length,errors},null,2));if(errors.length)process.exit(1);})().catch(e=>{console.error(e);process.exit(1)});
